```python
"""Graph utilities for shortest-path and reachability analysis."""
import heapq
from collections import deque
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Target: O((V+E) log V) using efficient priority queue.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    distances = {node: float('inf') for node in nodes}
    previous = {node: None for node in nodes}
    distances[source] = 0.0

    pq = [(0.0, source)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        if u == target:
            break

        if current_dist > distances[u]:
            continue

        for v, weight in graph.neighbors(u):
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                previous[v] = u
                heapq.heappush(pq, (distance, v))

    if distances[target] == float('inf'):
        return None, []

    path = []
    curr = target
    while curr is not None:
        path.append(curr)
        curr = previous[curr]

    return distances[target], path[::-1]


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Target: Single Dijkstra pass — O((V+E) log V).
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    distances = {node: float('inf') for node in nodes}
    previous = {node: None for node in nodes}
    distances[source] = 0.0

    pq = [(0.0, source)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > distances[u]:
            continue
        for v, weight in graph.neighbors(u):
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                previous[v] = u
                heapq.heappush(pq, (distance, v))

    result = {}
    for node in nodes:
        if distances[node] != float('inf'):
            path = []
            curr = node
            while curr is not None:
                path.append(curr)
                curr = previous[curr]
            result[node] = (distances[node], path[::-1])
    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Target: Early-termination Dijkstra — O(k log V + E).
    """
    if source not in graph.nodes:
        return []

    distances = {source: 0.0}
    pq = [(0.0, source)]
    results = []

    while pq and len(results) < k:
        current_dist, u = heapq.heappop(pq)

        if current_dist > distances.get(u, float('inf')):
            continue

        if u != source:
            results.append((u, current_dist))
            if len(results) == k:
                break

        for v, weight in graph.neighbors(u):
            distance = current_dist + weight
            if distance < distances.get(v, float('inf')):
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    return results


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.
    Target: Simple BFS — O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    visited = {source}
    queue = deque([source])

    while queue:
        u = queue.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).
    Target: BFS on undirected version — O(V + E).
    """
    nodes = list(graph.nodes)
    if not nodes:
        return []

    # Build undirected adjacency list
    undirected_adj = {node: [] for node in nodes}
    for edge in graph._edges:
        undirected_adj[edge.src].append(edge.dst)
        undirected_adj[edge.dst].append(edge.src)

    visited = set()
    components = []

    for node in nodes:
        if node not in visited:
            component = set()
            queue = deque([node])
            visited.add(node)
            while queue:
                u = queue.popleft()
                component.add(u)
                for v in undirected_adj[u]:
                    if v not in visited:
                        visited.add(v)
                        queue.append(v)
            components.append(component)

    return components
